import { overallState, type Service, type ServiceState, type StatusData } from "./services.ts";
import { averageUptime, dayLevel } from "./uptime.ts";

const STATE_LABEL: Record<ServiceState, string> = {
  operational: "Operational",
  degraded: "Degraded",
  outage: "Outage",
};

const BANNER: Record<ServiceState, string> = {
  operational: "All systems operational",
  degraded: "Some systems degraded",
  outage: "Major outage",
};

export function escapeHtml(text: string): string {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function day(since: string, offset: number): string {
  const d = new Date(`${since}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + offset);
  return d.toLocaleDateString("en-GB", { day: "numeric", month: "short", timeZone: "UTC" });
}

function renderService(s: Service, since: string): string {
  const days = s.uptime
    .map((pct, i) => `<li class="day ${dayLevel(pct)}" title="${day(since, i)} · ${pct}%"></li>`)
    .join("");
  return `
      <li class="service">
