import { readFileSync } from "node:fs";

export type ServiceState = "operational" | "degraded" | "outage";

export interface Service {
  id: string;
  name: string;
  description: string;
  status: ServiceState;
  // One figure per day, oldest first, ending today.
  uptime: number[];
}

export interface StatusData {
  updated: string;
  since: string;
  services: Service[];
}

const STATES: ServiceState[] = ["operational", "degraded", "outage"];

export function loadStatus(path = new URL("../data/services.json", import.meta.url)): StatusData {
  const data = JSON.parse(readFileSync(path, "utf8")) as StatusData;
  for (const s of data.services) {
    if (!STATES.includes(s.status)) throw new Error(`${s.id}: unknown status ${s.status}`);
  }
  return data;
}

// The worst state any service is in right now.
export function overallState(services: Service[]): ServiceState {
  if (services.some((s) => s.status === "outage")) return "outage";
  if (services.some((s) => s.status === "degraded")) return "degraded";
  return "operational";
}

