// How a day's uptime reads on the bar.
export type DayLevel = "up" | "degraded" | "down";

export function dayLevel(percent: number): DayLevel {
  if (percent >= 99.5) return "up";
  if (percent >= 97) return "degraded";
  return "down";
}

// The mean of the daily figures, to two decimals.
export function averageUptime(days: number[]): number {
  if (days.length === 0) return 100;
  const sum = days.reduce((a, b) => a + b, 0);
  return Math.round((sum / days.length) * 100) / 100;
}

