import { overallState, type Service, type ServiceState, type StatusData } from "./services.ts";
import { averageUptime, dayLevel } from "./uptime.ts";
import { type Incident, type IncidentSeverity } from "./incidents.ts";

const STATE_LABEL: Record<ServiceState, string> = {
  operational: "Operational",
  degraded: "Degraded",
  outage: "Outage",
};

const BANNER: Record<ServiceState, string> = {
  operational: "All systems operational",
  degraded: "Some systems degraded",
  outage: "Major outage",
};

const SEVERITY_LABEL: Record<IncidentSeverity, string> = {
  minor: "Minor",
  major: "Major",
};

function formatUtc(iso: string): string {
  return new Date(iso).toLocaleString("en-GB", {
    day: "numeric", month: "short", hour: "2-digit", minute: "2-digit", timeZone: "UTC",
  });
}

export function escapeHtml(text: string): string {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function day(since: string, offset: number): string {
  const d = new Date(`${since}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + offset);
  return d.toLocaleDateString("en-GB", { day: "numeric", month: "short", timeZone: "UTC" });
}

function renderService(s: Service, since: string): string {
  const days = s.uptime
    .map((pct, i) => `<li class="day ${dayLevel(pct)}" title="${day(since, i)} · ${pct}%"></li>`)
    .join("");
  return `
      <li class="service">
        <div class="service-head">
          <div>
            <h2>${escapeHtml(s.name)}</h2>
            <p class="desc">${escapeHtml(s.description)}</p>
          </div>
          <span class="state ${s.status}">${STATE_LABEL[s.status]}</span>
        </div>
        <ol class="bar" aria-label="Uptime, last ${s.uptime.length} days">${days}</ol>
        <div class="bar-legend">
          <span>${s.uptime.length} days ago</span>
          <span class="pct">${averageUptime(s.uptime).toFixed(2)}% uptime</span>
          <span>Today</span>
        </div>
      </li>`;
}

function renderIncident(inc: Incident): string {
  return `
        <li class="incident ${inc.severity}">
          <div class="incident-head">
            <span class="incident-service">${escapeHtml(inc.service)}</span>
            <span class="incident-sev">${SEVERITY_LABEL[inc.severity]}</span>
            <time class="incident-time" datetime="${inc.time}">${formatUtc(inc.time)}</time>
          </div>
          <p class="incident-note">${escapeHtml(inc.note)}</p>
        </li>`;
}

export function renderIncidents(incidents: Incident[]): string {
  if (incidents.length === 0) return "";
  return `
    <section aria-label="Incident history">
      <h2 class="section-title">Incident history</h2>
      <ol class="timeline">${incidents.map(renderIncident).join("")}
      </ol>
    </section>`;
}

export function renderPage(data: StatusData, incidents: Incident[] = []): string {
  const state = overallState(data.services);
  const updated = formatUtc(data.updated);
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Status</title>
  <link rel="stylesheet" href="/style.css">
</head>
<body>
  <main>
    <header>
      <p class="eyebrow">Status</p>
      <div class="banner ${state}">
        <span class="dot"></span>
        <div>
          <strong>${BANNER[state]}</strong>
          <span>Updated ${updated} UTC</span>
        </div>
      </div>
    </header>
    <section aria-label="Services">
      <ul class="services">${data.services.map((s) => renderService(s, data.since)).join("")}
      </ul>
    </section>
${renderIncidents(incidents)}
  </main>
</body>
</html>
`;
}

